from lib import *
S = SS('k16')
F1 = [['kubelet', '容器崩溃重启'], ['同样的事件', 'Pulled/Created/Started/BackOff'], ['合并', '同一个 Event,count 增加'], ['结果', 'Created 3→5, BackOff 2→4']]
F2 = [['同一个 Event 对象', 'uid 相同'], ['core/v1', 'count / firstTimestamp / lastTimestamp'], ['events.k8s.io/v1', 'deprecatedCount / deprecatedFirstTimestamp']]
F3 = [['Event key', 'lease = 非 0'], ['lease', 'TTL 3660 秒'], ['Pod key', 'lease = 0'], ['到期', 'Event 被 etcd 自动删除']]
F4 = [['Pod crash', '删除'], ['Event', '5 个仍然在'], ['kubectl events --for pod/crash', '照样能看'], ['kubectl describe pod', 'NotFound']]
PANELS = [('f', 'flow', '事件的产生与保留'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("Pod crash 的容器 exit 1 后被 kubelet 反复重启。20 秒时有 5 个 Event 对象:Pulled、Created、Started 的 count=3,BackOff 的 count=2;100 秒时仍然只有 5 个对象(不是更多),名字不变,count 变大了:Pulled 3→5、Created 3→5、Started 3→5、BackOff 2→4,lastTimestamp 也在更新。", f=fl(F1, cur=[2], done=[0, 1, 3]), t=tl(S(1), mark=lidx(S(1), '20 秒时', '100 秒时'), done=lidx(S(1), '同一个 Event 对象')), kv=KV([['同样的事件', '合并成同一个 Event 对象'], ['count / lastTimestamp', '重复一次加 1 并更新'], ['firstTimestamp', '保持第一次发生的时间']], ['同样的事件'])),
    step("同一个 BackOff 事件(crash.18dd1feacbf4fdde)分别从 core/v1 和 events.k8s.io/v1 读:core/v1 里 count=4、firstTimestamp、lastTimestamp、source.component=kubelet;events.k8s.io/v1 里 eventTime 和 series 都是空,同样的信息在 deprecatedCount=4、deprecatedFirstTimestamp 里,reportingController=kubelet。两者 uid 相同——是同一份存储的两个视图。", f=fl(F2, cur=[1, 2], done=[0]), t=tl(S(2), mark=lidx(S(2), 'core/v1:', 'events.k8s.io:'), done=lidx(S(2), 'uid 相同')), kv=KV([['core/v1', 'count / first / last 在顶层'], ['events.k8s.io/v1', 'kubelet 仍用旧的记录方式,新字段 series 为空'], ['存储', '同一份']], ['events.k8s.io/v1'])),
    step("etcd 里 /registry/events/k16/crash.18dd1feacbf4fdde 绑着 lease(非 0),etcdctl lease timetolive 显示 granted with TTL(3660s)、remaining(3646s);对比 kube-system 里一个 Pod 的 key,lease=0(永不过期)。到点 etcd 自动删除这个 key。", f=fl(F3, cur=[1], mark=[3], done=[0, 2]), t=tl(S(3), mark=lidx(S(3), 'granted with TTL', 'lease=非 0'), done=lidx(S(3), 'lease=0')), kv=KV([['保留时间', '约 1 小时(TTL 3660 秒)'], ['实现方式', 'etcd lease,不靠控制器清理'], ['普通对象', '没有 lease,不会自动过期']], ['保留时间'])),
    step("删除 Pod crash:kubectl get pod 得到 NotFound,kubectl describe pod 也是 NotFound;但 kubectl get events 仍然有 5 个对象,involvedObject 都指向 crash;kubectl events --for pod/crash 还能看到完整的事件,Pulled 一行是 (x5 over 103s)。", f=fl(F4, cur=[1, 2], done=[0], mark=[3]), t=tl(S(4), mark=lidx(S(4), 'NotFound', '仍然有 5 个对象'), done=lidx(S(4), 'kubectl events --for')), kv=KV([['事件与对象', '各自独立,Pod 没了事件还在'], ['排查已删除的 Pod', 'kubectl events --for 还能用'], ['过期', '到 TTL 才消失']], ['事件与对象'])),
]
A = mkartk('k16', 16, 'Kubernetes,Event,事件聚合,etcd lease,events.k8s.io,kubectl events,真实验证,动画演示',
    '在 kind 集群里让一个 Pod 反复崩溃重启,实测 Event 的行为:重复的事件不产生新对象,同一个 Event 的 count 增加(Created 3→5、BackOff 2→4);同一个事件在 core/v1 与 events.k8s.io/v1 里的字段差别;etcd 里每个事件 key 绑着 TTL 3660 秒的 lease,Pod 的 key 没有;Pod 删除之后事件仍然保留,kubectl events --for 还能查看。',
    'kubectl describe 最底下那几行 Events 是从哪来的?为什么崩溃的 Pod 每次重启不会让事件越攒越多?这篇用一个反复崩溃的 Pod 观察 Event 对象的 count 递增、两套 API 里的字段、etcd 里的过期机制,以及 Pod 删除之后事件还在的现象。',
    [('3→5 / 2→4', '100 秒内 Created、Pulled、Started 与 BackOff 事件的 count 变化(Event 对象数量始终是 5 个)'), ('TTL 3660 秒', 'etcd 里事件 key 绑着的 lease 的时长,Pod 的 key 没有 lease'), ('x5 over 103s', 'Pod 删除之后 kubectl events --for pod/crash 里 Pulled 一行的重复次数')],
    [('重复的事件会合并', '<p>容器 <code>exit 1</code> 后被 kubelet 按退避时间不停重启。20 秒时有 5 个 Event 对象,100 秒时仍然是 5 个——<code>Created</code>、<code>Pulled</code>、<code>Started</code> 从 <code>count=3</code> 涨到 5,<code>BackOff</code> 从 2 涨到 4,名字不变,<code>lastTimestamp</code> 不断更新,<code>firstTimestamp</code> 保持第一次的时间。kubelet 的事件记录器把“同一个来源、同一个对象、同一个原因和消息”的事件合并成一个对象,而不是每次新建一个。</p>'),
     ('两套 API', '<p>同一个 BackOff 事件从 <code>core/v1</code> 读,<code>count=4</code>、<code>firstTimestamp</code>、<code>lastTimestamp</code> 和 <code>source.component=kubelet</code> 都在顶层;从 <code>events.k8s.io/v1</code> 读,新 API 的 <code>eventTime</code>、<code>series</code> 是空的,这些信息放在 <code>deprecatedCount</code>、<code>deprecatedFirstTimestamp</code> 里,<code>reportingController=kubelet</code>。两者 <code>uid</code> 相同,是同一份存储的两个视图;写 Event 的组件用旧的记录方式,新 API 的 <code>series</code> 就不会有值。</p>'),
     ('事件什么时候消失', '<p>etcd 里 <code>/registry/events/…</code> 的每个 key 都绑着一个 lease:<code>etcdctl lease timetolive</code> 显示 <code>granted with TTL(3660s)</code>,到点 etcd 自己删除,不需要任何控制器清理;而 Pod 的 key <code>lease=0</code>,永不过期。所以事件只能回溯大约一小时。</p>'),
     ('Pod 没了,事件还在', '<p>删除 Pod 之后 <code>kubectl get pod</code> 和 <code>kubectl describe pod</code> 都是 NotFound,但 5 个 Event 对象仍在,<code>kubectl events --for pod/crash</code> 能看到完整的时间线(<code>Pulled</code> 一行是 <code>x5 over 103s</code>)。排查“已经被删掉的 Pod 为什么重启”时,事件往往是唯一的线索;而它不是持久的,一小时后就没有了。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);Pod crash 运行 busybox:1.36,命令 sh -c "echo boom; exit 1",默认 restartPolicy Always;事件分别用 kubectl get events -o json 和 kubectl get --raw /apis/events.k8s.io/v1/… 读取;lease 信息用 etcd 静态 Pod 里的 etcdctl get -w json 与 lease timetolive;两次快照在 Pod 创建后约 20 秒和 100 秒;每种情形各一次',
     '没有验证:事件的限流(客户端的 spam filter,同一来源短时间内能发多少事件)与“combined from similar events”聚合;--event-ttl 参数改变后的行为;使用 events.k8s.io 新记录方式的组件(series 有值)的情形;大量事件对 etcd 的压力;Event 的 reportingInstance 在控制器侧的写法;ImagePullBackOff 路径的事件(本机拉不到镜像,每次尝试约 30 秒,节奏太慢)'],
    '事件对象', PANELS)
